import React, { useMemo, useState, useEffect } from 'react';
import { 
  Users, 
  TrendingUp, 
  CheckCircle, 
  Clock,
  ArrowUpRight,
  ArrowDownRight,
  AlertCircle,
  Banknote,
  Target,
  Forward,
  Shield,
  Wand2,
  Sparkles,
  Loader2
} from 'lucide-react';
import { 
  AreaChart, 
  Area, 
  XAxis, 
  YAxis, 
  CartesianGrid, 
  Tooltip, 
  ResponsiveContainer
} from 'recharts';
import { GoogleGenAI } from '@google/genai';
import { User, Student } from '../types';
import { Language, translations } from '../services/localizationService';

interface DashboardProps {
  user: User;
  lang: Language;
  students: Student[];
}

export const Dashboard: React.FC<DashboardProps> = ({ user, lang, students = [] }) => {
  const t = translations[lang];
  const [aiBriefing, setAiBriefing] = useState<string>('');
  const [isBriefingLoading, setIsBriefingLoading] = useState(false);

  // Calculate accurate statistics from the students source of truth
  const stats = useMemo(() => {
    const totalExpected = students.reduce((sum, s) => sum + (Number(s.totalFee) || 0), 0);
    const totalCollected = students.reduce((sum, s) => sum + (Number(s.paidFee) || 0), 0);
    const totalArrears = students.reduce((sum, s) => sum + (Number(s.feeBalance) || 0), 0);
    const totalPrepaid = students.reduce((sum, s) => sum + (Number(s.prepaidFee) || 0), 0);

    const formatKES = (val: number) => {
      if (val >= 1000000) return (val / 1000000).toFixed(2) + 'M';
      if (val >= 1000) return (val / 1000).toFixed(1) + 'K';
      return val.toLocaleString();
    };

    const collectionRate = totalExpected > 0 ? (totalCollected / totalExpected) * 100 : 0;

    return {
      expected: formatKES(totalExpected),
      collected: formatKES(totalCollected),
      arrears: formatKES(totalArrears),
      prepaid: formatKES(totalPrepaid),
      rawExpected: totalExpected,
      rawCollected: totalCollected,
      studentCount: students.length,
      collectionRate: collectionRate.toFixed(1) + '%',
      attendanceRate: '94.2%',
      enrollmentChange: `+${Math.ceil(students.length * 0.05)} New this term`
    };
  }, [students]);

  // AI Briefing Logic
  useEffect(() => {
    const fetchBriefing = async () => {
      if (!process.env.API_KEY || aiBriefing) return;

      setIsBriefingLoading(true);
      try {
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
        const prompt = `You are a school management advisor for a Kenyan school. 
          Analyze these current stats:
          - Enrollment: ${stats.studentCount} students
          - Collection Rate: ${stats.collectionRate}
          - Total Collected: KES ${stats.collected}
          - Arrears: KES ${stats.arrears}
          - Attendance: ${stats.attendanceRate}

          Write a short, professional, and punchy 2-sentence executive summary (Principal's Briefing) for the dashboard. Use an encouraging tone.`;

        const response = await ai.models.generateContent({
          model: 'gemini-3-flash-preview',
          contents: prompt,
        });
        setAiBriefing(response.text || '');
      } catch (e) {
        setAiBriefing("School operations are stable. Focus on fee collection to meet Term 3 targets.");
      } finally {
        setIsBriefingLoading(false);
      }
    };

    fetchBriefing();
  }, [stats]);

  const chartData = useMemo(() => [
    { name: 'Term 1', collection: 3200000 },
    { name: 'Term 2', collection: 4100000 },
    { name: 'Term 3', collection: stats.rawCollected },
  ], [stats.rawCollected]);

  return (
    <div className="space-y-8 animate-in fade-in duration-700">
      {/* Principal's Briefing Card */}
      <div className="bg-gradient-to-r from-blue-700 via-blue-800 to-indigo-900 rounded-[40px] p-8 text-white shadow-2xl relative overflow-hidden group">
        <div className="absolute top-0 right-0 p-12 opacity-10 rotate-12 group-hover:scale-110 transition-transform duration-1000">
          <Sparkles size={160} />
        </div>
        <div className="relative z-10 flex flex-col md:flex-row md:items-center justify-between gap-8">
          <div className="space-y-4 max-w-2xl">
            <div className="flex items-center gap-3">
              <div className="bg-blue-400/20 p-2 rounded-xl backdrop-blur-md border border-white/10">
                <Wand2 className="w-5 h-5 text-blue-200" />
              </div>
              <h2 className="text-[10px] font-black uppercase tracking-[0.4em] text-blue-200">AI Principal's Briefing</h2>
            </div>
            {isBriefingLoading ? (
              <div className="flex items-center gap-3 text-blue-200/60 font-medium italic">
                <Loader2 className="w-4 h-4 animate-spin" />
                <span>Generating operational insights...</span>
              </div>
            ) : (
              <p className="text-2xl font-black tracking-tight leading-snug">
                {aiBriefing || "Initializing system diagnostics... Prepare for Term 3 closure reports."}
              </p>
            )}
          </div>
          <div className="bg-white/10 backdrop-blur-xl border border-white/20 p-6 rounded-[32px] shrink-0">
             <div className="flex items-center gap-4">
                <div className="w-12 h-12 bg-green-400 rounded-full flex items-center justify-center shadow-lg shadow-green-400/20">
                   <Shield className="w-6 h-6 text-green-900" />
                </div>
                <div>
                   <p className="text-[10px] font-black uppercase tracking-widest text-blue-100">System Integrity</p>
                   <p className="text-xl font-black text-white">OPTIMIZED</p>
                </div>
             </div>
          </div>
        </div>
      </div>

      <div className="flex flex-col md:flex-row md:items-end justify-between gap-4">
        <div>
          <h1 className="text-3xl font-black text-gray-900 tracking-tighter uppercase leading-none">{t.karibu}, {user.name.split(' ')[0]}</h1>
          <p className="text-gray-500 font-medium tracking-tight mt-2">Live School Financial & Operational Overview.</p>
        </div>
        <div className="bg-blue-50 px-4 py-2 rounded-2xl border border-blue-100 hidden md:block">
           <span className="text-[10px] font-black text-blue-600 uppercase tracking-widest">Global Collection Rate: {stats.collectionRate}</span>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        {[
          { label: "Total Invoiced", value: stats.expected, icon: Target, color: 'indigo', change: 'Current Year', positive: true },
          { label: "Fees Collected", value: stats.collected, icon: Banknote, color: 'green', change: stats.collectionRate + ' Rate', positive: true },
          { label: "Fee Balances", value: stats.arrears, icon: AlertCircle, color: 'red', change: 'Due Now', positive: false },
          { label: "Prepaid Credit", value: stats.prepaid, icon: Forward, color: 'blue', change: 'Future Terms', positive: true },
        ].map((stat, idx) => {
          const Icon = stat.icon;
          return (
            <div key={idx} className="bg-white p-6 rounded-3xl shadow-sm border border-gray-100 flex items-start justify-between group hover:shadow-xl hover:-translate-y-1 transition-all duration-300">
              <div className="min-w-0">
                <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest truncate mb-1">{stat.label}</p>
                <div className="flex items-baseline gap-1">
                   <span className="text-xs font-bold text-gray-300">KES</span>
                   <h3 className={`text-3xl font-black tracking-tighter ${stat.color === 'red' ? 'text-red-600' : stat.color === 'green' ? 'text-green-600' : 'text-gray-900'}`}>{stat.value}</h3>
                </div>
                <div className={`mt-3 flex items-center text-[10px] font-black uppercase tracking-widest ${stat.positive ? 'text-green-600' : 'text-red-500'}`}>
                  {stat.positive ? <CheckCircle className="w-3 h-3 mr-1" /> : <Clock className="w-3 h-3 mr-1" />}
                  {stat.change}
                </div>
              </div>
              <div className={`p-4 rounded-2xl transition-transform group-hover:scale-110 shrink-0 ${
                stat.color === 'blue' ? 'bg-blue-50 text-blue-600' : 
                stat.color === 'green' ? 'bg-green-50 text-green-600' : 
                stat.color === 'red' ? 'bg-red-50 text-red-600' : 
                stat.color === 'indigo' ? 'bg-indigo-50 text-indigo-600' :
                'bg-purple-50 text-purple-600'
              } border-2 border-white shadow-lg shadow-gray-100/50`}>
                <Icon className="w-6 h-6" />
              </div>
            </div>
          );
        })}
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
        <div className="bg-white p-8 rounded-[40px] shadow-sm border border-gray-100 overflow-hidden flex flex-col group hover:shadow-2xl transition-all duration-500">
          <div className="flex items-center justify-between mb-8">
            <div>
              <h3 className="text-xl font-black text-gray-800 uppercase tracking-tighter">Collection Velocity</h3>
              <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mt-1">Real-time KES Flow</p>
            </div>
            <div className="flex items-center gap-2 bg-gray-50 px-3 py-1.5 rounded-full text-[10px] font-black text-gray-500 uppercase">
              <TrendingUp className="w-3.5 h-3.5" /> Growth Trend
            </div>
          </div>
          <div className="w-full h-[350px] relative">
            <ResponsiveContainer width="100%" height="100%">
              <AreaChart data={chartData} margin={{ top: 10, right: 10, left: 10, bottom: 0 }}>
                <defs>
                  <linearGradient id="colorColl" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor="#2563eb" stopOpacity={0.2}/>
                    <stop offset="95%" stopColor="#2563eb" stopOpacity={0}/>
                  </linearGradient>
                </defs>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f8fafc" />
                <XAxis dataKey="name" stroke="#cbd5e1" fontSize={10} fontWeight="900" tickLine={false} axisLine={false} />
                <YAxis hide />
                <Tooltip 
                  cursor={{ stroke: '#2563eb', strokeWidth: 2, strokeDasharray: '5 5' }}
                  contentStyle={{ borderRadius: '24px', border: 'none', boxShadow: '0 25px 50px -12px rgb(0 0 0 / 0.15)', padding: '20px' }}
                  labelStyle={{ fontWeight: '900', textTransform: 'uppercase', fontSize: '12px', color: '#1e293b', marginBottom: '8px' }}
                  formatter={(value: any) => [`KES ${value.toLocaleString()}`, 'Total Collected']}
                />
                <Area type="monotone" dataKey="collection" stroke="#2563eb" strokeWidth={5} fillOpacity={1} fill="url(#colorColl)" animationDuration={2000} />
              </AreaChart>
            </ResponsiveContainer>
          </div>
        </div>

        <div className="grid grid-cols-1 sm:grid-cols-2 gap-6">
           <div className="bg-white p-8 rounded-[40px] shadow-sm border border-gray-100 hover:shadow-xl transition-all group">
              <div className="flex items-center gap-4 mb-6">
                 <div className="p-4 bg-blue-50 text-blue-600 rounded-[20px] shadow-sm group-hover:scale-110 transition-transform">
                    <Users className="w-6 h-6" />
                 </div>
                 <div>
                   <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest">{t.total_students}</p>
                   <p className="text-xs font-bold text-blue-600">Active Learners</p>
                 </div>
              </div>
              <h4 className="text-5xl font-black text-gray-900 tracking-tighter">{students.length}</h4>
              <p className="text-[10px] text-green-600 font-black uppercase mt-4 tracking-widest">{stats.enrollmentChange}</p>
           </div>

           <div className="bg-white p-8 rounded-[40px] shadow-sm border border-gray-100 hover:shadow-xl transition-all group">
              <div className="flex items-center gap-4 mb-6">
                 <div className="p-4 bg-emerald-50 text-emerald-600 rounded-[20px] shadow-sm group-hover:scale-110 transition-transform">
                    <CheckCircle className="w-6 h-6" />
                 </div>
                 <div>
                   <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest">{t.avg_attendance}</p>
                   <p className="text-xs font-bold text-emerald-600">Daily Average</p>
                 </div>
              </div>
              <h4 className="text-5xl font-black text-gray-900 tracking-tighter">94%</h4>
              <p className="text-[10px] text-blue-600 font-black uppercase mt-4 tracking-widest">Target Met for Term 3</p>
           </div>

           <div className="bg-gradient-to-br from-indigo-700 to-blue-900 p-8 rounded-[48px] shadow-2xl shadow-blue-200 text-white sm:col-span-2 relative overflow-hidden group">
              <div className="absolute top-0 right-0 p-12 opacity-5 rotate-12 group-hover:scale-110 transition-transform duration-700">
                 <Target size={200} />
              </div>
              <div className="relative z-10">
                <div className="flex justify-between items-start mb-10">
                   <div>
                      <h4 className="text-2xl font-black uppercase tracking-tighter">School Health Index</h4>
                      <p className="text-[10px] opacity-70 font-black uppercase tracking-[0.2em] mt-2">Operational Integrity Status</p>
                   </div>
                   <Shield className="w-10 h-10 text-blue-300" />
                </div>
                <div className="space-y-6">
                   <div className="space-y-2">
                      <div className="flex justify-between text-[11px] font-black uppercase tracking-widest">
                         <span>Fee Collection Goal</span>
                         <span className="text-green-300">{stats.collectionRate} Complete</span>
                      </div>
                      <div className="w-full h-2.5 bg-blue-800/50 rounded-full overflow-hidden border border-blue-400/20 shadow-inner">
                         <div className="h-full bg-green-400 shadow-[0_0_15px_rgba(74,222,128,0.5)] transition-all duration-1000" style={{ width: stats.collectionRate }}></div>
                      </div>
                   </div>
                   <div className="space-y-2">
                      <div className="flex justify-between text-[11px] font-black uppercase tracking-widest">
                         <span>SMS Communication</span>
                         <span className="text-blue-300">Live & Active</span>
                      </div>
                      <div className="w-full h-2.5 bg-blue-800/50 rounded-full overflow-hidden border border-blue-400/20 shadow-inner">
                         <div className="h-full bg-blue-300 shadow-[0_0_15px_rgba(147,197,253,0.5)] transition-all duration-1000" style={{ width: '100%' }}></div>
                      </div>
                   </div>
                </div>
              </div>
           </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { 
  LayoutDashboard, 
  Users, 
  UserSquare2,
  Wallet, 
  ClipboardCheck, 
  FileText, 
  Settings, 
  LogOut,
  Menu,
  X,
  Bell,
  Globe,
  BookOpen,
  ChevronDown,
  Shield,
  Calendar,
  MessageSquare,
  Smartphone,
  Search as SearchIcon,
  CheckCircle2,
  AlertCircle
} from 'lucide-react';
import { User, UserRole } from '../types';
import { Language, translations } from '../services/localizationService';

interface LayoutProps {
  user: User;
  currentTab: string;
  setCurrentTab: (tab: string) => void;
  isSidebarOpen: boolean;
  setIsSidebarOpen: (open: boolean) => void;
  logout: () => void;
  lang: Language;
  setLang: (lang: Language) => void;
  switchRole?: (role: UserRole) => void;
  installApp?: () => void;
  children: React.ReactNode;
}

export const Layout: React.FC<LayoutProps> = ({ 
  user, 
  currentTab, 
  setCurrentTab, 
  isSidebarOpen, 
  setIsSidebarOpen, 
  logout,
  lang,
  setLang,
  switchRole,
  installApp,
  children 
}) => {
  const t = translations[lang];
  const [searchTerm, setSearchTerm] = useState('');
  const [showNotifications, setShowNotifications] = useState(false);
  const [currentTime, setCurrentTime] = useState(new Date());
  const searchRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const timer = setInterval(() => setCurrentTime(new Date()), 1000);
    return () => clearInterval(timer);
  }, []);

  const hasAccess = (role: UserRole, tabId: string): boolean => {
    switch (tabId) {
      case 'dashboard': return true;
      case 'students': return [UserRole.ADMIN, UserRole.PRINCIPAL, UserRole.CLASS_TEACHER].includes(role);
      case 'staff': return [UserRole.ADMIN, UserRole.PRINCIPAL].includes(role);
      case 'academics': return [UserRole.ADMIN, UserRole.PRINCIPAL, UserRole.CLASS_TEACHER, UserRole.SUBJECT_TEACHER, UserRole.STUDENT].includes(role);
      case 'timetable': return true;
      case 'attendance': return [UserRole.ADMIN, UserRole.PRINCIPAL, UserRole.CLASS_TEACHER, UserRole.SUBJECT_TEACHER].includes(role);
      case 'messaging': return [UserRole.ADMIN, UserRole.PRINCIPAL].includes(role);
      case 'finance': return [UserRole.ADMIN, UserRole.PRINCIPAL].includes(role);
      case 'reports': return [UserRole.ADMIN, UserRole.PRINCIPAL, UserRole.CLASS_TEACHER, UserRole.SUBJECT_TEACHER].includes(role);
      case 'settings': return true;
      default: return false;
    }
  };

  const menuItems = [
    { id: 'dashboard', label: t.dashboard, icon: LayoutDashboard },
    { id: 'students', label: t.students, icon: Users },
    { id: 'staff', label: t.staff, icon: UserSquare2 },
    { id: 'academics', label: 'Academics', icon: BookOpen },
    { id: 'timetable', label: t.timetable, icon: Calendar },
    { id: 'attendance', label: t.attendance, icon: ClipboardCheck },
    { id: 'messaging', label: 'Messaging', icon: MessageSquare },
    { id: 'finance', label: t.finance, icon: Wallet },
    { id: 'reports', label: 'Reports', icon: FileText },
    { id: 'settings', label: 'Settings', icon: Settings },
  ].filter(item => hasAccess(user.role, item.id));

  // Mock Notifications
  const notifications = [
    { id: 1, text: 'Tuition payment received for ADM001', time: '2 mins ago', type: 'success' },
    { id: 2, text: 'Term 3 attendance report finalized', time: '1 hour ago', type: 'info' },
    { id: 3, text: 'Low SMS balance alert: 4,250 left', time: '3 hours ago', type: 'warning' },
  ];

  return (
    <div className="flex h-screen bg-gray-50 overflow-hidden font-sans">
      {/* Sidebar */}
      <aside className={`
        ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full'}
        fixed inset-y-0 left-0 z-50 w-64 bg-white border-r transform transition-transform duration-300 ease-in-out md:relative md:translate-x-0 shadow-lg md:shadow-none
      `}>
        <div className="p-6 border-b flex items-center justify-between">
          <div className="flex items-center space-x-2">
            <div className="bg-blue-600 p-2 rounded-lg shadow-md shadow-blue-200">
              <span className="text-white font-black text-xl leading-none">E</span>
            </div>
            <span className="text-xl font-black tracking-tighter text-gray-900">ElimuSmart</span>
          </div>
          <button onClick={() => setIsSidebarOpen(false)} className="md:hidden p-2 hover:bg-gray-100 rounded-lg">
            <X className="w-5 h-5" />
          </button>
        </div>

        <nav className="p-4 space-y-1 overflow-y-auto max-h-[calc(100vh-280px)]">
          {menuItems.map((item) => {
            const Icon = item.icon;
            return (
              <button
                key={item.id}
                onClick={() => { setCurrentTab(item.id); setIsSidebarOpen(false); }}
                className={`
                  w-full flex items-center space-x-3 px-4 py-3 rounded-xl transition-all duration-200
                  ${currentTab === item.id 
                    ? 'bg-blue-600 text-white shadow-lg shadow-blue-100' 
                    : 'text-gray-500 hover:bg-gray-50 hover:text-gray-900 font-medium'}
                `}
              >
                <Icon className={`w-5 h-5 ${currentTab === item.id ? 'text-white' : 'text-gray-400'}`} />
                <span className="font-bold text-sm tracking-tight">{item.label}</span>
              </button>
            );
          })}
        </nav>

        <div className="absolute bottom-0 w-full p-4 border-t bg-gray-50/50">
          {installApp && !window.matchMedia('(display-mode: standalone)').matches && (
            <div className="mb-4 p-4 bg-blue-600 rounded-2xl shadow-xl shadow-blue-200 text-white relative overflow-hidden group">
               <div className="absolute -right-2 -bottom-2 opacity-10 group-hover:scale-110 transition-transform">
                  <Smartphone className="w-16 h-16" />
               </div>
               <div className="relative z-10">
                 <h4 className="text-[10px] font-black uppercase tracking-widest opacity-80 mb-1">Get the App</h4>
                 <p className="text-[11px] font-bold leading-tight mb-3">Install ElimuSmart for the best experience.</p>
                 <button 
                  onClick={installApp}
                  className="w-full py-2 bg-white text-blue-600 rounded-xl text-[10px] font-black uppercase tracking-widest hover:bg-blue-50 transition-colors shadow-sm"
                 >
                   Install Now
                 </button>
               </div>
            </div>
          )}

          <div className="mb-4 px-4">
             <div className="text-[10px] font-black uppercase text-gray-400 tracking-widest mb-2">School Version</div>
             <div className="text-[10px] font-bold text-gray-600">v2.5.0 Enterprise</div>
          </div>
          <button 
            onClick={logout}
            className="w-full flex items-center space-x-3 px-4 py-3 text-red-600 hover:bg-red-50 rounded-xl transition-all font-bold text-sm"
          >
            <LogOut className="w-5 h-5" />
            <span>Logout</span>
          </button>
        </div>
      </aside>

      {/* Main Content Area */}
      <div className="flex-1 flex flex-col min-w-0 overflow-hidden">
        {/* Header */}
        <header className="h-20 bg-white border-b flex items-center justify-between px-4 md:px-8 z-30">
          <div className="flex items-center gap-4">
            <button onClick={() => setIsSidebarOpen(true)} className="md:hidden p-2 hover:bg-gray-100 rounded-lg">
              <Menu className="w-6 h-6" />
            </button>

            <div className="hidden lg:flex flex-col">
               <span className="text-xs font-black text-gray-400 uppercase tracking-widest">Nairobi, Kenya</span>
               <span className="text-sm font-black text-gray-900 tracking-tighter">
                 {currentTime.toLocaleTimeString('en-KE', { hour12: true, hour: '2-digit', minute: '2-digit' })}
               </span>
            </div>
          </div>

          <div className="flex-1 px-8 max-w-xl hidden md:block" ref={searchRef}>
            <div className="relative group">
              <input 
                type="text" 
                placeholder={t.search} 
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="w-full bg-gray-50 border border-gray-100 rounded-2xl py-2.5 px-10 focus:ring-4 focus:ring-blue-100 focus:bg-white outline-none transition-all shadow-inner"
              />
              <div className="absolute left-3.5 top-3 text-gray-400 group-focus-within:text-blue-500 transition-colors">
                <SearchIcon className="w-5 h-5" strokeWidth={2.5} />
              </div>

              {/* Search Results Mockup */}
              {searchTerm.length > 1 && (
                <div className="absolute top-full left-0 mt-2 w-full bg-white rounded-3xl shadow-2xl border border-gray-100 p-4 animate-in slide-in-from-top-2 duration-300 z-50">
                   <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest px-4 mb-3">Quick Search Results</p>
                   <div className="space-y-2">
                      <div className="p-3 hover:bg-blue-50 rounded-2xl transition-colors cursor-pointer flex items-center gap-4 group">
                         <div className="w-10 h-10 bg-blue-100 text-blue-600 rounded-xl flex items-center justify-center font-bold">K</div>
                         <div>
                            <p className="font-black text-sm text-gray-900 group-hover:text-blue-700 transition-colors">Kamau Njoroge</p>
                            <p className="text-[10px] font-bold text-gray-400 uppercase">ADM001 • Grade 7 Oak</p>
                         </div>
                      </div>
                      <div className="p-3 hover:bg-blue-50 rounded-2xl transition-colors cursor-pointer flex items-center gap-4 group">
                         <div className="w-10 h-10 bg-indigo-100 text-indigo-600 rounded-xl flex items-center justify-center font-bold">J</div>
                         <div>
                            <p className="font-black text-sm text-gray-900 group-hover:text-indigo-700 transition-colors">James Otieno</p>
                            <p className="text-[10px] font-bold text-gray-400 uppercase">TS001 • Staff • Mathematics</p>
                         </div>
                      </div>
                   </div>
                   <button 
                    onClick={() => { setCurrentTab('students'); setSearchTerm(''); }}
                    className="w-full mt-4 py-3 bg-gray-50 text-gray-500 rounded-2xl text-[10px] font-black uppercase tracking-widest hover:bg-gray-100 transition-colors"
                   >
                     Show all results
                   </button>
                </div>
              )}
            </div>
          </div>

          <div className="flex items-center space-x-3 lg:space-x-5">
            <button 
              onClick={() => setLang(lang === 'en' ? 'sw' : 'en')}
              className="hidden sm:flex items-center gap-1.5 px-3 py-1.5 bg-gray-100 rounded-full hover:bg-gray-200 transition text-[11px] font-black text-gray-700 uppercase"
            >
              <Globe className="w-4 h-4" />
              <span>{lang}</span>
            </button>

            <div className="relative">
              <button 
                onClick={() => setShowNotifications(!showNotifications)}
                className={`p-2.5 rounded-full relative transition-all ${showNotifications ? 'bg-blue-50 text-blue-600' : 'hover:bg-gray-100 text-gray-600'}`}
              >
                <Bell className="w-6 h-6" />
                <span className="absolute top-2 right-2.5 w-2 h-2 bg-red-500 rounded-full border-2 border-white"></span>
              </button>

              {/* Notifications Drawer */}
              {showNotifications && (
                <div className="absolute right-0 top-full mt-2 w-80 bg-white rounded-3xl shadow-2xl border border-gray-100 overflow-hidden z-50 animate-in fade-in zoom-in duration-300">
                   <div className="p-5 border-b flex items-center justify-between">
                      <h4 className="font-black text-gray-900 uppercase tracking-tighter">Notifications</h4>
                      <span className="text-[9px] font-black bg-blue-100 text-blue-600 px-2 py-0.5 rounded-full uppercase">3 New</span>
                   </div>
                   <div className="divide-y max-h-96 overflow-y-auto">
                      {notifications.map(n => (
                        <div key={n.id} className="p-4 hover:bg-gray-50 transition-colors flex gap-4">
                           <div className={`w-10 h-10 rounded-xl flex items-center justify-center shrink-0 ${n.type === 'success' ? 'bg-green-50 text-green-600' : n.type === 'warning' ? 'bg-red-50 text-red-600' : 'bg-blue-50 text-blue-600'}`}>
                              {n.type === 'success' ? <CheckCircle2 size={18} /> : <AlertCircle size={18} />}
                           </div>
                           <div>
                              <p className="text-xs font-bold text-gray-800 leading-snug">{n.text}</p>
                              <p className="text-[10px] font-medium text-gray-400 mt-1">{n.time}</p>
                           </div>
                        </div>
                      ))}
                   </div>
                   <button className="w-full py-4 text-[10px] font-black text-blue-600 uppercase bg-blue-50/50 hover:bg-blue-50 transition-colors border-t border-blue-50">
                     Clear All Notifications
                   </button>
                </div>
              )}
            </div>

            <div className="flex items-center space-x-3 border-l pl-5">
              <div className="text-right hidden sm:block">
                <div className="text-sm font-black text-gray-900 tracking-tight leading-none mb-1">{user.name}</div>
                <div className="text-[9px] font-black text-blue-600 uppercase tracking-widest">{user.role.replace('_', ' ')}</div>
              </div>
              <div className="relative group">
                <img src={user.avatar} className="w-10 h-10 rounded-full border-2 border-white shadow-md cursor-pointer hover:ring-4 hover:ring-blue-100 transition-all" alt="Profile" />
                <div className="absolute right-0 top-full mt-2 w-48 bg-white border rounded-2xl shadow-2xl opacity-0 invisible group-hover:opacity-100 group-hover:visible transition-all p-2 z-50">
                  <div className="px-4 py-2 border-b mb-1">
                     <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Portal Role</p>
                     <p className="text-xs font-black text-blue-600">{user.role}</p>
                  </div>
                  {Object.values(UserRole).map(role => (
                    <button 
                      key={role}
                      onClick={() => switchRole?.(role)}
                      className="w-full text-left px-4 py-2 text-[10px] font-bold uppercase hover:bg-blue-50 rounded-xl transition-colors text-gray-600"
                    >
                      Login as {role.replace('_', ' ')}
                    </button>
                  ))}
                </div>
              </div>
            </div>
          </div>
        </header>

        {/* Scrollable Page Body */}
        <div className="flex-1 overflow-y-auto no-print scroll-smooth">
          {children}
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { 
  BookOpen, 
  Plus, 
  Search, 
  ChevronRight, 
  Save, 
  Wand2, 
  CheckCircle2, 
  AlertCircle,
  Loader2,
  Filter,
  ArrowLeft,
  BookMarked,
  Trash2,
  Edit3,
  X,
  Tags,
  CalendarDays,
  LayoutGrid,
  Type,
  Layers,
  GraduationCap,
  UserX
} from 'lucide-react';
import { GoogleGenAI } from '@google/genai';
import { Exam, MarkEntry, CBCGrade, KENYAN_CLASSES, SCHOOL_STREAMS, Student, ExamResult } from '../types';
import { schoolService } from '../services/schoolService';
import { Language, translations } from '../services/localizationService';

interface Subject {
  id: string;
  name: string;
  category: string;
  gradeRange: string;
}

const INITIAL_SUBJECTS: Subject[] = [
  { id: 'sub1', name: 'Mathematics', category: 'STEM', gradeRange: 'PP1 - Grade 9' },
  { id: 'sub2', name: 'English Language', category: 'Languages', gradeRange: 'Grade 1 - Grade 9' },
  { id: 'sub3', name: 'Kiswahili', category: 'Languages', gradeRange: 'Grade 1 - Grade 9' },
  { id: 'sub4', name: 'Integrated Science', category: 'STEM', gradeRange: 'Grade 7 - Grade 9' },
  { id: 'sub5', name: 'Creative Arts', category: 'Arts', gradeRange: 'PP1 - Grade 9' },
  { id: 'sub6', name: 'Pre-Technical Studies', category: 'Technical', gradeRange: 'Grade 7 - Grade 9' },
];

interface AcademicsProps {
  lang: Language;
  students: Student[];
  setStudents: React.Dispatch<React.SetStateAction<Student[]>>;
}

export const AcademicsModule: React.FC<AcademicsProps> = ({ lang, students = [], setStudents }) => {
  const t = translations[lang];
  const [view, setView] = useState<'exams' | 'mark-entry' | 'subjects'>('exams');

  const [exams, setExams] = useState<Exam[]>([]);
  const [isExamModalOpen, setIsExamModalOpen] = useState(false);
  const [editingExam, setEditingExam] = useState<Exam | null>(null);
  const [examSearch, setExamSearch] = useState('');
  const [examFormData, setExamFormData] = useState<Partial<Exam>>({
    title: '',
    term: 1,
    year: new Date().getFullYear(),
    type: 'CAT',
    date: new Date().toISOString().split('T')[0]
  });

  const [subjects, setSubjects] = useState<Subject[]>(() => {
    const saved = localStorage.getItem('elimusmart_curriculum');
    return saved ? JSON.parse(saved) : INITIAL_SUBJECTS;
  });

  const [isSubjectModalOpen, setIsSubjectModalOpen] = useState(false);
  const [editingSubject, setEditingSubject] = useState<Subject | null>(null);
  const [subjectSearch, setSubjectSearch] = useState('');
  const [subjectFormData, setSubjectFormData] = useState({ 
    name: '', 
    category: 'STEM', 
    gradeRange: 'Grade 1 - Grade 9' 
  });

  const [selectedExam, setSelectedExam] = useState<Exam | null>(null);
  const [selectedSubject, setSelectedSubject] = useState('Mathematics');
  const [selectedClass, setSelectedClass] = useState('Grade 7');
  const [selectedStream, setSelectedStream] = useState(''); // Default to empty (All Streams)
  const [marks, setMarks] = useState<MarkEntry[]>([]);
  const [isSaving, setIsSaving] = useState(false);
  const [isGeneratingRemarks, setIsGeneratingRemarks] = useState<string | null>(null);

  useEffect(() => {
    schoolService.getExams().then(setExams);
  }, []);

  useEffect(() => {
    localStorage.setItem('elimusmart_curriculum', JSON.stringify(subjects));
  }, [subjects]);

  // Sync marks whenever filters change while in mark-entry mode
  useEffect(() => {
    if (view === 'mark-entry' && selectedExam) {
      const classStudents = students.filter(s => 
        s.class.toLowerCase() === selectedClass.toLowerCase() && 
        (selectedStream === '' || s.stream.toLowerCase() === selectedStream.toLowerCase())
      );

      const entries: MarkEntry[] = classStudents.map(s => {
        const existing = s.results?.find(r => r.examId === selectedExam.id && r.subject === selectedSubject);
        return {
          studentId: s.id,
          studentName: `${s.firstName} ${s.lastName}`,
          admissionNumber: s.admissionNumber,
          score: existing?.score || 0,
          competency: existing?.competency || CBCGrade.BE,
          remarks: existing?.remarks || ''
        };
      });
      setMarks(entries);
    }
  }, [selectedClass, selectedStream, selectedSubject, selectedExam, view, students]);

  const filteredExams = useMemo(() => {
    return exams.filter(ex => 
      ex.title.toLowerCase().includes(examSearch.toLowerCase()) ||
      ex.type.toLowerCase().includes(examSearch.toLowerCase())
    );
  }, [exams, examSearch]);

  const filteredSubjects = useMemo(() => {
    return subjects.filter(s => 
      s.name.toLowerCase().includes(subjectSearch.toLowerCase()) ||
      s.category.toLowerCase().includes(subjectSearch.toLowerCase())
    );
  }, [subjects, subjectSearch]);

  const handleOpenMarkEntry = (exam: Exam) => {
    setSelectedExam(exam);
    setView('mark-entry');
  };

  const openExamModal = (exam?: Exam) => {
    if (exam) {
      setEditingExam(exam);
      setExamFormData({
        title: exam.title,
        term: exam.term,
        year: exam.year,
        type: exam.type,
        date: exam.date
      });
    } else {
      setEditingExam(null);
      setExamFormData({
        title: '',
        term: 1,
        year: new Date().getFullYear(),
        type: 'CAT',
        date: new Date().toISOString().split('T')[0]
      });
    }
    setIsExamModalOpen(true);
  };

  const handleSaveExam = (e: React.FormEvent) => {
    e.preventDefault();
    if (editingExam) {
      setExams(prev => prev.map(ex => 
        ex.id === editingExam.id ? { ...ex, ...examFormData } as Exam : ex
      ));
    } else {
      const newExam: Exam = {
        id: `ex${Date.now()}`,
        title: examFormData.title || 'New Assessment',
        term: examFormData.term || 1,
        year: examFormData.year || new Date().getFullYear(),
        type: examFormData.type as any || 'CAT',
        date: examFormData.date || new Date().toISOString().split('T')[0]
      };
      setExams(prev => [newExam, ...prev]);
    }
    setIsExamModalOpen(false);
  };

  const handleDeleteExam = (id: string) => {
    if (confirm('Are you sure you want to delete this exam and all associated records?')) {
      setExams(prev => prev.filter(ex => ex.id !== id));
    }
  };

  const openSubjectModal = (subject?: Subject) => {
    if (subject) {
      setEditingSubject(subject);
      setSubjectFormData({ 
        name: subject.name, 
        category: subject.category, 
        gradeRange: subject.gradeRange 
      });
    } else {
      setEditingSubject(null);
      setSubjectFormData({ 
        name: '', 
        category: 'STEM', 
        gradeRange: 'Grade 1 - Grade 9' 
      });
    }
    setIsSubjectModalOpen(true);
  };

  const handleSaveSubject = (e: React.FormEvent) => {
    e.preventDefault();
    if (editingSubject) {
      setSubjects(prev => prev.map(s => 
        s.id === editingSubject.id ? { ...s, ...subjectFormData } : s
      ));
    } else {
      const newSub: Subject = {
        id: `sub${Date.now()}`,
        ...subjectFormData
      };
      setSubjects(prev => [...prev, newSub]);
    }
    setIsSubjectModalOpen(false);
  };

  const handleDeleteSubject = (id: string) => {
    if (confirm('Are you sure you want to remove this subject from the school curriculum?')) {
      setSubjects(prev => prev.filter(s => s.id !== id));
    }
  };

  const handleScoreChange = (studentId: string, scoreStr: string) => {
    const score = parseInt(scoreStr) || 0;
    setMarks(prev => prev.map(m => 
      m.studentId === studentId 
        ? { ...m, score, competency: schoolService.calculateCBCGrade(score) } 
        : m
    ));
  };

  const handleRemarkChange = (studentId: string, remarks: string) => {
    setMarks(prev => prev.map(m => m.studentId === studentId ? { ...m, remarks } : m));
  };

  const generateAIRemark = async (student: MarkEntry) => {
    if (!process.env.API_KEY) {
      handleRemarkChange(student.studentId, `${student.studentName} shows ${student.competency} in ${selectedSubject}. Keep it up!`);
      return;
    }

    setIsGeneratingRemarks(student.studentId);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const promptText = `Write a one-sentence professional teacher remark for a student named ${student.studentName} who scored ${student.score}% (CBC level: ${student.competency}) in ${selectedSubject}. Make it encouraging and specific to the grade level ${selectedClass}.`;

      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: promptText
      });
      handleRemarkChange(student.studentId, response.text || 'Commendable performance.');
    } catch (error) {
      console.error(error);
      handleRemarkChange(student.studentId, 'Performance is within expectations.');
    } finally {
      setIsGeneratingRemarks(null);
    }
  };

  const saveMarks = async () => {
    if (marks.length === 0) {
      alert("No student marks to commit.");
      return;
    }

    setIsSaving(true);
    await new Promise(r => setTimeout(r, 1200));

    setStudents(prev => prev.map(student => {
      const markEntry = marks.find(m => m.studentId === student.id);
      if (markEntry && selectedExam) {
        const result: ExamResult = {
          examId: selectedExam.id,
          subject: selectedSubject,
          score: markEntry.score,
          grade: markEntry.score >= 80 ? 'A' : markEntry.score >= 60 ? 'B' : markEntry.score >= 40 ? 'C' : 'D',
          competency: markEntry.competency,
          remarks: markEntry.remarks
        };

        const existingResults = student.results || [];
        const filteredResults = existingResults.filter(r => !(r.examId === selectedExam.id && r.subject === selectedSubject));

        return {
          ...student,
          results: [...filteredResults, result]
        };
      }
      return student;
    }));

    setIsSaving(false);
    alert('Marks successfully recorded and synced with student report cards.');
    setView('exams');
  };

  return (
    <div className="space-y-6 animate-in fade-in duration-500">
      <datalist id="kenyan-classes">
        {KENYAN_CLASSES.map(c => <option key={c} value={c} />)}
      </datalist>
      <datalist id="school-streams">
        <option value="">All Streams</option>
        {SCHOOL_STREAMS.map(s => <option key={s} value={s} />)}
      </datalist>

      <div className="flex flex-col md:flex-row md:items-center justify-between gap-6">
        <div>
          <h1 className="text-3xl font-black text-gray-900 tracking-tighter uppercase italic leading-none">Academics Engine</h1>
          <p className="text-gray-400 font-bold uppercase text-[10px] tracking-[0.3em] mt-3 flex items-center gap-3">
             <span className="w-2 h-2 bg-purple-500 rounded-full animate-pulse"></span>
             CBC Assessment Control • Flexible Routing
          </p>
        </div>

        <div className="flex flex-wrap gap-2 no-print">
          {view === 'exams' && (
            <>
              <button 
                onClick={() => setView('subjects')}
                className="flex items-center space-x-3 bg-white border-2 border-gray-100 text-gray-600 px-6 py-3 rounded-2xl hover:bg-gray-50 hover:border-purple-200 transition-all font-black uppercase text-[10px] tracking-widest shadow-sm"
              >
                <BookMarked className="w-5 h-5 text-purple-500" />
                <span>Curriculum</span>
              </button>
              <button 
                onClick={() => openExamModal()}
                className="flex items-center space-x-3 bg-gray-900 text-white px-8 py-3 rounded-2xl hover:bg-black transition-all font-black uppercase text-[10px] tracking-widest shadow-xl shadow-gray-200 border-b-4 border-black"
              >
                <Plus className="w-5 h-5" />
                <span>Schedule Exam</span>
              </button>
            </>
          )}
          {view === 'subjects' && (
            <>
              <button 
                onClick={() => setView('exams')}
                className="flex items-center space-x-3 bg-white border-2 border-gray-100 text-gray-600 px-6 py-3 rounded-2xl hover:bg-gray-50 transition-all font-black uppercase text-[10px] tracking-widest shadow-sm"
              >
                <ArrowLeft className="w-5 h-5 text-blue-500" />
                <span>Back to Exams</span>
              </button>
              <button 
                onClick={() => openSubjectModal()}
                className="flex items-center space-x-3 bg-purple-600 text-white px-8 py-3 rounded-2xl hover:bg-purple-700 transition-all font-black uppercase text-[10px] tracking-widest shadow-xl shadow-purple-100 border-b-4 border-purple-800"
              >
                <Plus className="w-5 h-5" />
                <span>Add Subject</span>
              </button>
            </>
          )}
        </div>
      </div>

      {/* GLOBAL FILTERS: Visible in both Exams and Mark Entry views */}
      {view !== 'subjects' && (
        <div className="bg-white p-6 rounded-[32px] border-2 border-gray-50 flex flex-col xl:flex-row items-center gap-6 no-print shadow-xl">
           <div className="flex-1 w-full grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
              <div className="space-y-2">
                 <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Academic Target (Class)</label>
                 <div className="flex items-center bg-gray-50 border-2 border-gray-100 rounded-2xl focus-within:border-blue-500 transition-all px-4 py-1 shadow-inner">
                   <Type size={16} className="text-gray-400 mr-2" />
                   <input 
                     list="kenyan-classes"
                     value={selectedClass}
                     placeholder="Select Grade..."
                     onChange={e => setSelectedClass(e.target.value)}
                     className="w-full bg-transparent py-2.5 font-black uppercase text-[11px] outline-none placeholder:text-gray-300"
                   />
                 </div>
              </div>

              <div className="space-y-2">
                 <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Section / Stream</label>
                 <div className="flex items-center bg-gray-50 border-2 border-gray-100 rounded-2xl focus-within:border-blue-500 transition-all px-4 py-1 shadow-inner">
                   <Layers size={16} className="text-gray-400 mr-2" />
                   <input 
                     list="school-streams"
                     value={selectedStream}
                     placeholder="All Streams"
                     onChange={e => setSelectedStream(e.target.value)}
                     className="w-full bg-transparent py-2.5 font-black uppercase text-[11px] outline-none placeholder:text-gray-300"
                   />
                 </div>
              </div>

              <div className="space-y-2">
                 <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Learning Area</label>
                 <select 
                   value={selectedSubject} 
                   onChange={e => setSelectedSubject(e.target.value)}
                   className="w-full p-3.5 bg-gray-50 border-2 border-gray-100 rounded-2xl font-black uppercase text-[11px] focus:border-blue-500 outline-none transition-all shadow-inner"
                 >
                   {subjects.map(s => <option key={s.id} value={s.name}>{s.name}</option>)}
                 </select>
              </div>
           </div>

           {view === 'exams' && (
             <div className="w-full xl:w-64 self-end">
                <div className="relative">
                    <input 
                      type="text"
                      placeholder="Filter assessments..."
                      value={examSearch}
                      onChange={e => setExamSearch(e.target.value)}
                      className="w-full pl-10 pr-4 py-3.5 bg-white border-2 border-gray-100 rounded-2xl focus:border-blue-500 outline-none font-black text-[11px] uppercase"
                    />
                    <Filter className="absolute left-3 top-4 w-4 h-4 text-gray-300" />
                </div>
             </div>
           )}
        </div>
      )}

      {view === 'exams' && (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {filteredExams.map(exam => (
            <div key={exam.id} className="bg-white p-8 rounded-[40px] border-2 border-gray-50 shadow-sm hover:shadow-2xl transition-all group relative overflow-hidden">
              <div className="absolute -top-4 -right-4 p-8 opacity-5 group-hover:scale-110 transition-transform">
                <GraduationCap className="w-32 h-32" />
              </div>

              <div className="flex justify-between items-start mb-8">
                <div className="p-4 bg-blue-50 text-blue-600 rounded-2xl border-2 border-white shadow-sm">
                  <BookOpen className="w-6 h-6" />
                </div>
                <div className="flex gap-2 no-print opacity-0 group-hover:opacity-100 transition-all translate-x-4 group-hover:translate-x-0">
                  <button onClick={() => openExamModal(exam)} className="p-3 bg-white text-gray-400 hover:text-blue-600 rounded-xl transition-all border-2 border-gray-50 hover:border-blue-100 shadow-sm"><Edit3 className="w-5 h-5" /></button>
                  <button onClick={() => handleDeleteExam(exam.id)} className="p-3 bg-white text-gray-400 hover:text-red-600 rounded-xl transition-all border-2 border-gray-50 hover:border-red-100 shadow-sm"><Trash2 className="w-5 h-5" /></button>
                </div>
              </div>

              <div className="space-y-2">
                <h3 className="text-2xl font-black text-gray-900 tracking-tighter leading-none uppercase italic">{exam.title}</h3>
                <div className="flex items-center gap-3 text-[10px] font-black text-blue-500 uppercase tracking-widest">
                  <span className="bg-blue-50 px-2 py-0.5 rounded-md">Term {exam.term} • {exam.year}</span>
                  <span className="w-1.5 h-1.5 bg-gray-200 rounded-full"></span>
                  <span className="text-gray-400">{exam.type}</span>
                </div>
              </div>

              <div className="mt-10 flex items-center justify-between gap-4">
                <div className="text-[10px] font-black text-gray-400 uppercase tracking-[0.2em] flex items-center gap-2">
                  <CalendarDays className="w-4 h-4 text-blue-500" />
                  {new Date(exam.date).toLocaleDateString('en-GB', { day: '2-digit', month: 'short' })}
                </div>
                <button 
                  onClick={() => handleOpenMarkEntry(exam)}
                  className="flex items-center gap-3 bg-gray-900 text-white px-6 py-3 rounded-2xl text-[10px] font-black uppercase tracking-widest hover:bg-black transition-all shadow-xl active:scale-95 border-b-4 border-black"
                >
                  Enter Marks <ChevronRight className="w-4 h-4" />
                </button>
              </div>
            </div>
          ))}
          {filteredExams.length === 0 && (
            <div className="col-span-full py-24 text-center bg-white rounded-[48px] border-2 border-dashed border-gray-100">
               <CalendarDays className="w-16 h-16 text-gray-100 mx-auto mb-6" />
               <p className="text-[12px] font-black uppercase text-gray-400 tracking-[0.4em] italic">No scheduled assessments matching your filters.</p>
            </div>
          )}
        </div>
      )}

      {view === 'subjects' && (
        <div className="bg-white rounded-[48px] shadow-2xl border-2 border-gray-50 overflow-hidden">
           <div className="p-10 border-b bg-gray-50/50 flex flex-col lg:flex-row lg:items-center justify-between gap-6">
              <div className="relative flex-1 max-w-lg">
                <Search className="absolute left-4 top-4 w-5 h-5 text-gray-400" />
                <input 
                  type="text" 
                  placeholder="Search global curriculum..." 
                  value={subjectSearch}
                  onChange={e => setSubjectSearch(e.target.value)}
                  className="w-full pl-12 pr-4 py-4 bg-white border-2 border-gray-100 rounded-[24px] focus:ring-8 focus:ring-purple-500/10 focus:border-purple-500 outline-none font-black text-[11px] uppercase tracking-widest shadow-inner" 
                />
