                       <p className="text-[10px] text-gray-400 font-black uppercase tracking-[0.3em] mt-3">Ready for UTF-8 Global Release</p>
                     </div>
                     <div className="flex gap-3">
                       <select value={targetClass} onChange={e => setTargetClass(e.target.value)} className="p-4 bg-white border-2 border-gray-100 rounded-2xl text-[10px] font-black uppercase tracking-widest outline-none focus:border-blue-500 transition-all shadow-sm">
                         <option>All Classes</option>
