    <div className={`p-3 rounded-2xl mb-3 transition-transform group-hover:scale-110 shadow-sm ${active ? 'bg-white text-blue-600' : 'bg-gray-50 text-gray-300'}`}>
       <Icon className="w-6 h-6" />
