             <p className="text-[10px] text-gray-400 font-black uppercase tracking-widest leading-relaxed">
               Authorized Personnel Only. System activity is encrypted.
             </p>
          </div>
        </div>
      </div>
    );
  }

  return (
    <Layout 
      user={user} 
      currentTab={currentTab} 
      setCurrentTab={setCurrentTab}
      isSidebarOpen={isSidebarOpen}
      setIsSidebarOpen={setIsSidebarOpen}
      logout={() => setUser(null)}
      lang={lang}
      setLang={setLang}
      switchRole={switchRole}
      installApp={(deferredPrompt || isIOS) ? () => setShowInstallPop(true) : undefined}
    >
      {showInstallPop && (
        <div className="fixed top-6 left-1/2 -translate-x-1/2 z-[200] w-full max-w-md px-4 animate-in slide-in-from-top-4 duration-500 no-print">
          <div className="bg-white rounded-[32px] shadow-[0_25px_60px_rgba(0,0,0,0.3)] p-6 border-2 border-blue-50 flex items-center gap-6 relative overflow-hidden">
             <div className="absolute top-0 right-0 p-4 opacity-5 pointer-events-none">
                <Smartphone size={100} />
             </div>
             <div className="bg-blue-600 text-white p-4 rounded-2xl shadow-xl shadow-blue-100 shrink-0">
                <DownloadCloud size={24} />
             </div>
             <div className="flex-1">
                <h4 className="text-sm font-black text-gray-900 uppercase tracking-tight">{isIOS ? 'Install on iPhone' : 'Offline Access Ready'}</h4>
                <p className="text-[11px] font-bold text-gray-500 leading-tight mt-1">
                  {isIOS ? 'Tap "Share" and then "Add to Home Screen" to install ElimuSmart.' : 'Install the app for faster access and offline capabilities.'}
                </p>
                <div className="flex gap-2 mt-4">
                   {!isIOS && (
                     <button onClick={handleInstallApp} className="bg-blue-600 text-white px-5 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest shadow-lg shadow-blue-100 flex items-center gap-2">
                       <Check size={14} /> Install Now
                     </button>
                   )}
                   {isIOS && (
                     <div className="flex items-center gap-2 text-[10px] font-black uppercase text-blue-600 bg-blue-50 px-3 py-2 rounded-xl border border-blue-100">
                        <Share size={14} /> iOS Menu
                     </div>
                   )}
                   <button onClick={() => setShowInstallPop(false)} className="bg-gray-100 text-gray-500 px-5 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest hover:bg-gray-200 transition-colors">
                     Dismiss
                   </button>
                </div>
             </div>
             <button onClick={() => setShowInstallPop(false)} className="absolute top-4 right-4 text-gray-300 hover:text-red-500 transition-colors"><X size={18} /></button>
          </div>
        </div>
      )}

      <main className="p-4 md:p-8 max-w-[1600px] mx-auto">
        {currentTab === 'dashboard' && <Dashboard user={user} lang={lang} students={students} />}
        {currentTab === 'students' && <StudentManagement students={students} setStudents={setStudents} feeStructure={feeStructure} />}
        {currentTab === 'staff' && <StaffManagement />}
        {currentTab === 'academics' && <AcademicsModule lang={lang} students={students} setStudents={setStudents} schoolConfig={schoolConfig} />}
        {currentTab === 'timetable' && <TimetableModule lang={lang} />}
        {currentTab === 'finance' && <FinanceModule lang={lang} students={students} setStudents={setStudents} feeStructure={feeStructure} setFeeStructure={setFeeStructure} schoolLogo={schoolLogo} schoolConfig={schoolConfig} />}
        {currentTab === 'attendance' && <AttendanceModule lang={lang} />}
        {currentTab === 'messaging' && <MessagingModule lang={lang} students={students} />}
        {currentTab === 'reports' && <ReportsModule lang={lang} students={students} schoolLogo={schoolLogo} schoolConfig={schoolConfig} />}
        {currentTab === 'settings' && (
          <SettingsModule 
            currentUser={user} 
            users={users} 
            setUsers={setUsers} 
            schoolLogo={schoolLogo} 
            setSchoolLogo={setSchoolLogo} 
            schoolConfig={schoolConfig}
            setSchoolConfig={setSchoolConfig}
          />
        )}
      </main>
    </Layout>
  );
};

export default App;

import React, { useState, useEffect, useMemo } from 'react';
import { 
  Settings as SettingsIcon, 
  School, 
  Calendar, 
  Shield, 
  Bell, 
  User, 
  Save, 
  Loader2, 
  Database,
  History,
  Lock,
  Upload,
  Camera,
  Trash2,
  Users,
  Plus,
  Key,
  Smartphone,
  Banknote,
  CreditCard,
  Hash,
  Edit3,
  X,
  ShieldCheck,
  UserPlus,
  RefreshCw,
  Clock as ClockIcon
} from 'lucide-react';
import { UserRole, User as UserType } from '../types';

interface SettingsModuleProps {
  currentUser: UserType;
  users: UserType[];
  setUsers: React.Dispatch<React.SetStateAction<UserType[]>>;
  schoolLogo: string | null;
  setSchoolLogo: (logo: string | null) => void;
  schoolConfig: any;
  setSchoolConfig: React.Dispatch<React.SetStateAction<any>>;
}

export const SettingsModule: React.FC<SettingsModuleProps> = ({ 
  currentUser, 
  users, 
  setUsers, 
  schoolLogo, 
  setSchoolLogo,
  schoolConfig,
  setSchoolConfig
}) => {
  const [activeSection, setActiveSection] = useState<'profile' | 'school' | 'academic' | 'security' | 'users'>('profile');
  const [isSaving, setIsSaving] = useState(false);

  // Security State
  const [currentPassword, setCurrentPassword] = useState('');
  const [newPassword, setNewPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');

  // School Edit State
  const [editableConfig, setEditableConfig] = useState(schoolConfig);

  // Sync editableConfig when schoolConfig changes
  useEffect(() => {
    setEditableConfig(schoolConfig);
  }, [schoolConfig]);

  // Unified User Modal State
  const [isUserModalOpen, setIsUserModalOpen] = useState(false);
  const [editingUser, setEditingUser] = useState<UserType | null>(null);
  const [userFormData, setUserFormData] = useState<Partial<UserType>>({
    name: '',
    email: '',
    role: UserRole.SUBJECT_TEACHER,
    password: ''
  });

  const isAdmin = currentUser.role === UserRole.ADMIN;
  const isAdminOrPrincipal = currentUser.role === UserRole.ADMIN || currentUser.role === UserRole.PRINCIPAL;

  // Auto Term Calculation for Preview
  const sysTime = useMemo(() => {
    const now = new Date();
    const year = now.getFullYear();
    const month = now.getMonth();
    let term = 1;
    if (month >= 4 && month <= 7) term = 2;
    else if (month >= 8) term = 3;
    return { year, term };
  }, []);

  const handleLogoChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setSchoolLogo(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleUpdatePassword = async (e: React.FormEvent) => {
    e.preventDefault();
    if (newPassword !== confirmPassword) {
      alert('Error: New passwords do not match.');
      return;
    }
    if (currentPassword !== currentUser.password) {
      alert('Error: Current password is incorrect.');
      return;
    }

    setIsSaving(true);
    await new Promise(r => setTimeout(r, 1000));

    setUsers(prev => prev.map(u => u.id === currentUser.id ? { ...u, password: newPassword } : u));

    setIsSaving(false);
    alert('Security Update: Password successfully changed.');
    setCurrentPassword('');
    setNewPassword('');
    setConfirmPassword('');
  };

  const openUserModal = (user?: UserType) => {
    if (user) {
      setEditingUser(user);
      setUserFormData({
        name: user.name,
        email: user.email,
        role: user.role,
        password: user.password || ''
      });
    } else {
      setEditingUser(null);
      setUserFormData({ name: '', email: '', role: UserRole.SUBJECT_TEACHER, password: '' });
    }
    setIsUserModalOpen(true);
  };

  const handleSaveUser = (e: React.FormEvent) => {
    e.preventDefault();
    if (!userFormData.name || !userFormData.email) return;

    if (editingUser) {
      setUsers(prev => prev.map(u => u.id === editingUser.id ? { ...u, ...userFormData } : u));
      alert(`Account for ${userFormData.name} updated successfully.`);
    } else {
      const userToAdd: UserType = {
        id: `u${Date.now()}`,
        name: userFormData.name || '',
        email: (userFormData.email || '').toLowerCase(),
        role: userFormData.role as UserRole,
        password: userFormData.password || 'password123',
        avatar: `https://api.dicebear.com/7.x/avataaars/svg?seed=${userFormData.name}`
      };
      setUsers(prev => [...prev, userToAdd]);
      alert(`New account created for ${userFormData.name}.`);
    }
    setIsUserModalOpen(false);
  };

  const handleDeleteUser = (id: string) => {
    if (id === currentUser.id) {
      alert("Error: You cannot delete your own active session.");
      return;
    }
    const target = users.find(u => u.id === id);
    if (window.confirm(`Security Warning: Are you sure you want to permanently revoke access for ${target?.name}?`)) {
      setUsers(prev => prev.filter(u => u.id !== id));
    }
  };

  const handleSaveSchoolInfo = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSaving(true);
    await new Promise(r => setTimeout(r, 1500));
    setSchoolConfig(editableConfig);
    setIsSaving(false);
    alert('School configuration updated successfully!');
  };

  const syncAcademicClock = () => {
    setEditableConfig({ ...editableConfig, year: sysTime.year, term: sysTime.term });
    alert(`System synchronized to: ${sysTime.year} Term ${sysTime.term}`);
  };

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-black text-gray-800 tracking-tight uppercase">System Management</h1>
          <p className="text-gray-500 font-medium">Core platform configuration and administrative controls.</p>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
        <div className="md:col-span-1 space-y-1">
          <nav className="bg-white rounded-2xl border border-gray-100 p-2 shadow-sm">
            <NavItem icon={User} label="Personal Profile" active={activeSection === 'profile'} onClick={() => setActiveSection('profile')} />
            {isAdminOrPrincipal && (
              <>
                <NavItem icon={School} label="School Profile" active={activeSection === 'school'} onClick={() => setActiveSection('school')} />
                <NavItem icon={Calendar} label="Academic Term" active={activeSection === 'academic'} onClick={() => setActiveSection('academic')} />
              </>
            )}
            {isAdmin && (
              <NavItem icon={Users} label="User Accounts" active={activeSection === 'users'} onClick={() => setActiveSection('users')} />
            )}
            <NavItem icon={Lock} label="Security" active={activeSection === 'security'} onClick={() => setActiveSection('security')} />
          </nav>
        </div>

        <div className="md:col-span-3">
          <div className="bg-white rounded-2xl border border-gray-100 shadow-sm overflow-hidden min-h-[500px]">

            {activeSection === 'profile' && (
              <div className="p-8 space-y-6 animate-in fade-in duration-300">
                <h3 className="text-lg font-black border-b pb-4 uppercase tracking-tight text-gray-800">My Identity</h3>
                <div className="flex items-center gap-6 p-6 bg-gray-50 rounded-2xl">
                   <img src={currentUser.avatar} className="w-20 h-20 rounded-2xl border-4 border-white shadow-md" alt="Avatar" />
                   <div>
                      <p className="text-2xl font-black text-gray-900 leading-none">{currentUser.name}</p>
                      <p className="text-xs font-black text-blue-600 uppercase tracking-widest mt-2">{currentUser.role.replace('_', ' ')}</p>
                      <p className="text-[10px] text-gray-400 font-medium mt-1">{currentUser.email}</p>
                   </div>
                </div>
              </div>
            )}

            {activeSection === 'users' && isAdmin && (
              <div className="p-8 space-y-6 animate-in fade-in duration-300">
                <div className="flex items-center justify-between border-b pb-4">
                   <h3 className="text-lg font-black uppercase tracking-tight text-gray-800">Platform Users</h3>
                   <button onClick={() => openUserModal()} className="flex items-center gap-2 bg-blue-600 text-white px-5 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest hover:bg-blue-700 transition-all shadow-lg shadow-blue-100">
                     <UserPlus className="w-4 h-4" /> Create Account
                   </button>
                </div>

                <div className="divide-y border rounded-2xl overflow-hidden">
                  {users.map(u => (
                    <div key={u.id} className="p-4 flex items-center justify-between hover:bg-gray-50 transition-colors group">
                       <div className="flex items-center gap-4">
                          <div className="relative">
                            <img src={u.avatar} className="w-12 h-12 rounded-xl border bg-white" />
                            {u.id === currentUser.id && (
                              <div className="absolute -top-1 -right-1 bg-green-500 w-3 h-3 rounded-full border-2 border-white"></div>
                            )}
                          </div>
                          <div>
                            <p className="font-black text-gray-900 text-sm">{u.name} {u.id === currentUser.id && <span className="text-[10px] bg-gray-100 px-1.5 py-0.5 rounded ml-1 font-bold text-gray-400 tracking-normal">YOU</span>}</p>
                            <div className="flex items-center gap-2 mt-0.5">
                              <span className="text-[9px] font-black bg-blue-50 text-blue-600 px-1.5 py-0.5 rounded uppercase tracking-wider">{u.role.replace('_', ' ')}</span>
                              <span className="text-[10px] text-gray-400 font-medium">{u.email}</span>
                            </div>
                          </div>
                       </div>
                       <div className="flex items-center gap-2">
                          <button 
                            onClick={() => openUserModal(u)}
                            className="p-2.5 text-gray-400 hover:text-blue-600 hover:bg-blue-50 rounded-xl transition-all border border-transparent hover:border-blue-100"
                            title="Update Credentials"
                          >
                            <Edit3 className="w-4 h-4" />
                          </button>
                          <button 
                            onClick={() => handleDeleteUser(u.id)}
                            className={`p-2.5 text-gray-400 hover:text-red-600 hover:bg-red-50 rounded-xl transition-all border border-transparent hover:border-red-100 ${u.id === currentUser.id ? 'opacity-20 cursor-not-allowed' : ''}`}
                            title="Revoke Access"
                            disabled={u.id === currentUser.id}
                          >
                            <Trash2 className="w-4 h-4" />
                          </button>
                       </div>
                    </div>
                  ))}
                </div>
                <div className="p-4 bg-gray-50 rounded-xl border border-gray-100 flex items-start gap-3">
                   <ShieldCheck className="w-5 h-5 text-gray-400 mt-0.5" />
                   <p className="text-[10px] font-bold text-gray-500 uppercase tracking-widest leading-relaxed italic">
                     Only Administrators can manage user accounts. Changes to roles affect portal visibility and permissions immediately.
                   </p>
                </div>
              </div>
            )}

            {activeSection === 'security' && (
              <form onSubmit={handleUpdatePassword} className="p-8 space-y-8 animate-in fade-in duration-300">
                <div className="flex items-center gap-4 border-b pb-4">
                   <Key className="text-blue-600 w-6 h-6" />
                   <h3 className="text-lg font-black uppercase tracking-tight text-gray-800">Credentials Management</h3>
                </div>

                <div className="max-w-md space-y-6">
                   <div className="space-y-1">
                      <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Current Password</label>
                      <input required type="password" value={currentPassword} onChange={e => setCurrentPassword(e.target.value)} className="w-full p-4 bg-gray-50 border-2 border-transparent rounded-2xl font-bold outline-none focus:border-blue-500 focus:bg-white transition-all shadow-inner" />
                   </div>
                   <div className="space-y-4">
                      <div className="space-y-1">
                        <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">New Password</label>
                        <input required type="password" value={newPassword} onChange={e => setNewPassword(e.target.value)} className="w-full p-4 bg-gray-50 border-2 border-transparent rounded-2xl font-bold outline-none focus:border-blue-500 focus:bg-white transition-all shadow-inner" />
                      </div>
                      <div className="space-y-1">
                        <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Confirm New Password</label>
                        <input required type="password" value={confirmPassword} onChange={e => setConfirmPassword(e.target.value)} className="w-full p-4 bg-gray-50 border-2 border-transparent rounded-2xl font-bold outline-none focus:border-blue-500 focus:bg-white transition-all shadow-inner" />
                      </div>
                   </div>
                   <button 
                    type="submit"
                    disabled={isSaving}
                    className="w-full py-4 bg-gray-900 text-white rounded-2xl font-black uppercase tracking-widest hover:bg-black transition-all shadow-xl shadow-gray-200 disabled:opacity-50 flex items-center justify-center gap-3"
                   >
                     {isSaving ? <Loader2 className="w-5 h-5 animate-spin" /> : <Save className="w-5 h-5" />}
                     Commit Security Change
                   </button>
                </div>
              </form>
            )}

            {activeSection === 'school' && isAdminOrPrincipal && (
              <form onSubmit={handleSaveSchoolInfo} className="p-8 space-y-8 animate-in fade-in duration-300">
                <h3 className="text-lg font-black border-b pb-4 text-blue-900 uppercase tracking-tight">Institutional Profile</h3>

                <div className="flex flex-col sm:flex-row gap-8 p-8 bg-blue-50/50 rounded-3xl border border-blue-100 relative">
                  <div className="relative group z-10">
                    <div className="w-40 h-40 rounded-3xl bg-white border-4 border-white shadow-2xl flex items-center justify-center overflow-hidden">
                      <img src={schoolLogo || `https://api.dicebear.com/7.x/initials/svg?seed=${editableConfig?.schoolName || 'School'}&backgroundColor=1e3a8a&fontFamily=Inter&fontSize=45&bold=true`} alt="Logo" className="w-full h-full object-cover" />
                    </div>
                    <label className="absolute -bottom-3 -right-3 bg-blue-600 text-white p-3 rounded-2xl shadow-xl cursor-pointer hover:bg-blue-700 transition-all border-4 border-white">
                      <Camera className="w-5 h-5" />
                      <input type="file" className="hidden" accept="image/*" onChange={handleLogoChange} />
                    </label>
                  </div>

                  <div className="flex-1 flex flex-col justify-center">
                    <h4 className="text-xl font-black text-blue-900 uppercase tracking-tight">{editableConfig?.schoolName}</h4>
                    <p className="text-[10px] text-blue-600 font-black uppercase tracking-widest mt-1 opacity-70">Main Digital Seal</p>
                    <div className="mt-6 flex gap-3">
                       <button type="button" onClick={() => setSchoolLogo(null)} className="text-[10px] font-black uppercase text-red-500 hover:text-red-700 transition-colors">Remove Custom Logo</button>
                    </div>
                  </div>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  <div className="space-y-1">
                    <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Official Name</label>
                    <input type="text" value={editableConfig?.schoolName} onChange={e => setEditableConfig({...editableConfig, schoolName: e.target.value})} className="w-full p-3 border rounded-xl font-bold outline-none focus:border-blue-500" />
                  </div>
                  <div className="space-y-1">
                    <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Reg No.</label>
                    <input type="text" value={editableConfig?.registrationNo} onChange={e => setEditableConfig({...editableConfig, registrationNo: e.target.value})} className="w-full p-3 border rounded-xl font-mono font-bold outline-none focus:border-blue-500" />
                  </div>
                  <div className="col-span-2 space-y-1">
                    <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">School Motto</label>
                    <input type="text" value={editableConfig?.motto} onChange={e => setEditableConfig({...editableConfig, motto: e.target.value})} className="w-full p-3 border rounded-xl font-bold outline-none focus:border-blue-500" />
                  </div>
                </div>

                <div className="pt-6 border-t mt-8">
                   <div className="flex items-center gap-3 mb-6">
                      <Banknote className="text-blue-600 w-6 h-6" />
                      <h3 className="text-lg font-black text-blue-900 uppercase tracking-tight">Financial Disbursement Details</h3>
                   </div>

                   <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                      <div className="space-y-4">
                         <div className="flex items-center gap-2 mb-2">
                            <Smartphone className="w-4 h-4 text-green-600" />
                            <p className="text-[10px] font-black uppercase text-gray-400 tracking-widest">M-Pesa Merchant Accounts</p>
                         </div>
                         <div className="grid grid-cols-2 gap-4">
                            <div className="space-y-1">
                               <label className="text-[9px] font-black text-gray-400 uppercase tracking-widest ml-1">Paybill No.</label>
                               <input type="text" placeholder="e.g. 522522" value={editableConfig?.mpesaPaybill} onChange={e => setEditableConfig({...editableConfig, mpesaPaybill: e.target.value})} className="w-full p-3 bg-gray-50 border-2 border-transparent rounded-xl font-black focus:border-green-500 outline-none transition-all shadow-inner" />
                            </div>
                            <div className="space-y-1">
                               <label className="text-[9px] font-black text-gray-400 uppercase tracking-widest ml-1">Buy Goods Till</label>
                               <input type="text" placeholder="e.g. 123456" value={editableConfig?.mpesaTill} onChange={e => setEditableConfig({...editableConfig, mpesaTill: e.target.value})} className="w-full p-3 bg-gray-50 border-2 border-transparent rounded-xl font-black focus:border-green-500 outline-none transition-all shadow-inner" />
                            </div>
                         </div>
                      </div>

                      <div className="space-y-4">
                         <div className="flex items-center gap-2 mb-2">
                            <CreditCard className="w-4 h-4 text-blue-600" />
                            <p className="text-[10px] font-black uppercase text-gray-400 tracking-widest">Official Bank Account</p>
                         </div>
                         <div className="grid grid-cols-2 gap-4">
                            <div className="space-y-1">
                               <label className="text-[9px] font-black text-gray-400 uppercase tracking-widest ml-1">Bank Name</label>
                               <input type="text" placeholder="e.g. Equity Bank" value={editableConfig?.bankName} onChange={e => setEditableConfig({...editableConfig, bankName: e.target.value})} className="w-full p-3 bg-gray-50 border-2 border-transparent rounded-xl font-black focus:border-blue-500 outline-none transition-all shadow-inner" />
                            </div>
                            <div className="space-y-1">
                               <label className="text-[9px] font-black text-gray-400 uppercase tracking-widest ml-1">Account No.</label>
                               <input type="text" placeholder="0123456789" value={editableConfig?.bankAccountNumber} onChange={e => setEditableConfig({...editableConfig, bankAccountNumber: e.target.value})} className="w-full p-3 bg-gray-50 border-2 border-transparent rounded-xl font-black focus:border-blue-500 outline-none transition-all shadow-inner" />
                            </div>
                         </div>
                      </div>
                   </div>
                   <p className="mt-4 text-[9px] text-gray-400 font-bold uppercase tracking-widest italic flex items-center gap-2 bg-gray-50 p-3 rounded-xl border border-gray-100">
                      <Hash size={10} className="text-blue-500" /> These details will appear on official fee statements and printed invoices generated for guardians.
                   </p>
                </div>

                <div className="flex justify-end pt-6 border-t mt-10">
                   <button type="submit" disabled={isSaving} className="bg-gray-900 text-white px-10 py-4 rounded-2xl font-black uppercase text-xs tracking-widest shadow-2xl hover:bg-black transition-all flex items-center gap-3 border-b-4 border-black active:scale-95">
                     {isSaving ? <Loader2 className="w-4 h-4 animate-spin" /> : <Save className="w-4 h-4" />}
                     Commit Profile Updates
                   </button>
                </div>
              </form>
            )}

            {activeSection === 'academic' && isAdminOrPrincipal && (
              <div className="p-8 space-y-10 animate-in fade-in duration-300">
                <div className="flex items-center justify-between border-b pb-6">
                   <div>
                      <h3 className="text-xl font-black text-indigo-900 uppercase tracking-tight">Academic Timeline</h3>
                      <p className="text-[10px] text-gray-400 font-black uppercase tracking-widest mt-1">Configure active year and term logic</p>
                   </div>
                   <div className="flex items-center gap-2 bg-indigo-50 px-4 py-2 rounded-full border border-indigo-100">
                      <div className="w-2 h-2 bg-green-500 rounded-full animate-pulse shadow-[0_0_10px_rgba(34,197,94,0.5)]"></div>
                      <span className="text-[9px] font-black text-indigo-600 uppercase tracking-[0.2em]">Automated Timezone Sync Active</span>
                   </div>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                   <div className="p-8 bg-indigo-50/50 rounded-[40px] border-2 border-indigo-100 relative group overflow-hidden">
                      <div className="absolute top-0 right-0 p-8 opacity-[0.03] group-hover:scale-110 transition-transform"><ClockIcon size={120} /></div>
                      <h4 className="text-[10px] font-black text-indigo-400 uppercase tracking-widest mb-6">Current Active Cycle</h4>
                      <div className="flex gap-10">
                         <div>
                            <p className="text-[9px] font-black text-gray-400 uppercase tracking-widest mb-1 opacity-60">Year</p>
                            <p className="text-5xl font-black text-indigo-900 tracking-tighter leading-none">{editableConfig?.year}</p>
                         </div>
                         <div className="w-[2px] bg-indigo-200/50"></div>
                         <div>
                            <p className="text-[9px] font-black text-gray-400 uppercase tracking-widest mb-1 opacity-60">Session</p>
                            <p className="text-5xl font-black text-indigo-900 tracking-tighter leading-none">Term {editableConfig?.term}</p>
                         </div>
                      </div>
                      <button 
                        onClick={syncAcademicClock}
                        className="mt-10 w-full flex items-center justify-center gap-3 bg-white border-2 border-indigo-100 py-4 rounded-2xl text-[10px] font-black uppercase tracking-[0.2em] text-indigo-600 hover:bg-indigo-600 hover:text-white hover:border-indigo-600 transition-all shadow-lg shadow-indigo-100/50"
                      >
                         <RefreshCw size={14} className="animate-spin-slow" /> Reset to System Clock
                      </button>
                   </div>

                   <div className="space-y-6">
                      <div className="p-8 bg-gray-50 rounded-[40px] border-2 border-gray-100 space-y-6">
                         <h4 className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-2">Manual Session Override</h4>
                         <div className="grid grid-cols-2 gap-4">
                            <div className="space-y-1">
                               <label className="text-[9px] font-black text-gray-400 uppercase tracking-widest ml-1">Academic Year</label>
                               <select 
                                  value={editableConfig?.year} 
                                  onChange={e => setEditableConfig({...editableConfig, year: parseInt(e.target.value)})}
                                  className="w-full p-4 bg-white border-2 border-gray-100 rounded-2xl font-black text-xl outline-none focus:border-indigo-500 shadow-sm"
                               >
                                  {[2024, 2025, 2026, 2027].map(y => <option key={y} value={y}>{y}</option>)}
                               </select>
                            </div>
                            <div className="space-y-1">
                               <label className="text-[9px] font-black text-gray-400 uppercase tracking-widest ml-1">Current Term</label>
                               <select 
                                  value={editableConfig?.term} 
                                  onChange={e => setEditableConfig({...editableConfig, term: parseInt(e.target.value)})}
                                  className="w-full p-4 bg-white border-2 border-gray-100 rounded-2xl font-black text-xl outline-none focus:border-indigo-500 shadow-sm"
                               >
                                  {[1, 2, 3].map(t => <option key={t} value={t}>Term {t}</option>)}
                               </select>
                            </div>
                         </div>
                         <button 
                           onClick={handleSaveSchoolInfo}
                           disabled={isSaving}
                           className="w-full bg-indigo-900 text-white py-4 rounded-2xl font-black uppercase text-[10px] tracking-[0.3em] shadow-2xl hover:bg-black transition-all flex items-center justify-center gap-3 border-b-4 border-black"
                         >
                            {isSaving ? <Loader2 size={16} className="animate-spin" /> : <Save size={16} />}
                            Update Global Timeline
                         </button>
                      </div>
                   </div>
                </div>

                <div className="p-8 bg-blue-50/50 rounded-[40px] border-2 border-blue-100 flex items-start gap-6">
                   <div className="p-4 bg-white rounded-3xl shadow-sm border border-blue-50"><RefreshCw className="text-blue-600 w-6 h-6" /></div>
                   <div>
                      <p className="text-xs font-black text-blue-900 uppercase tracking-widest mb-1 italic">Propagated Syncing</p>
                      <p className="text-[11px] font-medium text-blue-800 leading-relaxed">
                        Updating the Global Academic Cycle will automatically set defaults for all new exams, report card generations, and financial fee invoicing across the platform. Current system detected: <strong className="uppercase">Nairobi/Kenyan Timezone Standard</strong>.
                      </p>
                   </div>
                </div>
              </div>
            )}
          </div>
        </div>
      </div>

      {/* Unified User Modal (Add/Update) */}
      {isUserModalOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-gray-900/80 backdrop-blur-md animate-in fade-in duration-200">
           <div className="bg-white rounded-[40px] w-full max-w-lg shadow-2xl relative overflow-hidden animate-in zoom-in duration-300">
              <div className="p-8 border-b bg-gray-50/50 flex items-center justify-between">
                 <div className="flex items-center gap-4">
                    <div className="w-12 h-12 bg-blue-100 rounded-2xl flex items-center justify-center text-blue-600 shadow-sm border-2 border-white">
                      {editingUser ? <Edit3 size={24} /> : <UserPlus size={24} />}
                    </div>
                    <div>
                        <h2 className="text-2xl font-black text-gray-900 uppercase tracking-tighter leading-none">{editingUser ? 'Update Account' : 'New Credentials'}</h2>
                        <p className="text-[10px] text-gray-400 font-black uppercase tracking-[0.2em] mt-2">{editingUser ? 'Modify Secure System Account' : 'Create Secure System Account'}</p>
                    </div>
                 </div>
                 <button onClick={() => setIsUserModalOpen(false)} className="p-4 hover:bg-red-50 text-gray-400 hover:text-red-500 rounded-full transition-all">
                    <X className="w-6 h-6" />
                 </button>
              </div>

              <form onSubmit={handleSaveUser} className="p-8 space-y-6">
                 <div className="space-y-4">
                    <div className="space-y-1">
                       <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Full Name</label>
                       <input required type="text" value={userFormData.name} onChange={e => setUserFormData({...userFormData, name: e.target.value})} className="w-full p-4 bg-gray-50 border-2 border-transparent rounded-2xl font-bold outline-none focus:border-blue-500 focus:bg-white transition-all shadow-inner" placeholder="John Doe" />
                    </div>
                    <div className="space-y-1">
                       <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Email Address</label>
                       <input required type="email" value={userFormData.email} onChange={e => setUserFormData({...userFormData, email: e.target.value})} className="w-full p-4 bg-gray-50 border-2 border-transparent rounded-2xl font-bold outline-none focus:border-blue-500 focus:bg-white transition-all shadow-inner" placeholder="name@school.ac.ke" />
                    </div>
                    <div className="space-y-1">
                       <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">System Role</label>
                       <select value={userFormData.role} onChange={e => setUserFormData({...userFormData, role: e.target.value as UserRole})} className="w-full p-4 bg-gray-50 border-2 border-transparent rounded-2xl font-black uppercase text-xs outline-none focus:border-blue-500 focus:bg-white transition-all shadow-inner">
                          {Object.values(UserRole).map(r => <option key={r} value={r}>{r.replace('_', ' ')}</option>)}
                       </select>
                    </div>
                    <div className="space-y-1">
                       <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">{editingUser ? 'Reset Password (Optional)' : 'Initial Password'}</label>
                       <input type="password" value={userFormData.password} onChange={e => setUserFormData({...userFormData, password: e.target.value})} className="w-full p-4 bg-gray-50 border-2 border-transparent rounded-2xl font-bold outline-none focus:border-blue-500 focus:bg-white transition-all shadow-inner" placeholder="••••••••" />
                    </div>
                 </div>

                 <div className="flex gap-4 pt-6">
                    <button type="button" onClick={() => setIsUserModalOpen(false)} className="flex-1 py-5 text-gray-400 font-black uppercase text-[10px] tracking-widest">Discard</button>
                    <button type="submit" className="flex-[2] py-5 bg-blue-600 text-white rounded-2xl font-black uppercase text-[10px] tracking-[0.2em] shadow-xl shadow-blue-100 hover:bg-blue-700 transition-all active:scale-95 border-b-4 border-blue-800 flex items-center justify-center gap-3">
                       {editingUser ? <Save size={18} /> : <UserPlus size={18} />}
                       {editingUser ? 'Save Changes' : 'Confirm Account'}
                    </button>
                 </div>
              </form>
           </div>
        </div>
      )}
    </div>
  );
};

const NavItem: React.FC<{ icon: any, label: string, active: boolean, onClick: () => void }> = ({ icon: Icon, label, active, onClick }) => (
  <button 
    onClick={onClick}
    className={`w-full flex items-center gap-4 px-5 py-4 rounded-xl text-sm font-black uppercase tracking-tighter transition-all ${active ? 'bg-blue-600 text-white shadow-lg shadow-blue-100' : 'text-gray-500 hover:bg-gray-50 hover:text-gray-900'}`}
  >
    <Icon className={`w-5 h-5 ${active ? 'text-white' : 'text-gray-400'}`} />
    <span>{label}</span>
  </button>
);

import React, { useState, useEffect, useMemo } from 'react';
import { 
  BookOpen, 
  Plus, 
  Search, 
  ChevronRight, 
  Save, 
  Wand2, 
  CheckCircle2, 
  AlertCircle,
  Loader2,
  Filter,
  ArrowLeft,
  BookMarked,
  Trash2,
  Edit3,
  X,
  Tags,
  CalendarDays,
  LayoutGrid,
  Type,
  Layers,
  GraduationCap,
  UserX
} from 'lucide-react';
import { GoogleGenAI } from '@google/genai';
import { Exam, MarkEntry, CBCGrade, KENYAN_CLASSES, SCHOOL_STREAMS, Student, ExamResult } from '../types';
import { schoolService } from '../services/schoolService';
import { Language, translations } from '../services/localizationService';

interface Subject {
  id: string;
  name: string;
  category: string;
  gradeRange: string;
}

const INITIAL_SUBJECTS: Subject[] = [
  { id: 'sub1', name: 'Mathematics', category: 'STEM', gradeRange: 'PP1 - Grade 9' },
  { id: 'sub2', name: 'English Language', category: 'Languages', gradeRange: 'Grade 1 - Grade 9' },
  { id: 'sub3', name: 'Kiswahili', category: 'Languages', gradeRange: 'Grade 1 - Grade 9' },
  { id: 'sub4', name: 'Integrated Science', category: 'STEM', gradeRange: 'Grade 7 - Grade 9' },
  { id: 'sub5', name: 'Creative Arts', category: 'Arts', gradeRange: 'PP1 - Grade 9' },
  { id: 'sub6', name: 'Pre-Technical Studies', category: 'Technical', gradeRange: 'Grade 7 - Grade 9' },
];

interface AcademicsProps {
  lang: Language;
  students: Student[];
  setStudents: React.Dispatch<React.SetStateAction<Student[]>>;
  schoolConfig?: any;
}

export const AcademicsModule: React.FC<AcademicsProps> = ({ lang, students = [], setStudents, schoolConfig }) => {
  const t = translations[lang];
  const [view, setView] = useState<'exams' | 'mark-entry' | 'subjects'>('exams');

  const [exams, setExams] = useState<Exam[]>([]);
  const [isExamModalOpen, setIsExamModalOpen] = useState(false);
  const [editingExam, setEditingExam] = useState<Exam | null>(null);
  const [examSearch, setExamSearch] = useState('');

  const [examFormData, setExamFormData] = useState<Partial<Exam>>({
    title: '',
    term: schoolConfig?.term || 1,
    year: schoolConfig?.year || new Date().getFullYear(),
    type: 'CAT',
    date: new Date().toISOString().split('T')[0]
  });

  const [subjects, setSubjects] = useState<Subject[]>(() => {
    const saved = localStorage.getItem('elimusmart_curriculum');
    return saved ? JSON.parse(saved) : INITIAL_SUBJECTS;
  });

  const [isSubjectModalOpen, setIsSubjectModalOpen] = useState(false);
  const [editingSubject, setEditingSubject] = useState<Subject | null>(null);
  const [subjectSearch, setSubjectSearch] = useState('');
  const [subjectFormData, setSubjectFormData] = useState({ 
    name: '', 
    category: 'STEM', 
    gradeRange: 'Grade 1 - Grade 9' 
  });

  const [selectedExam, setSelectedExam] = useState<Exam | null>(null);
  const [selectedSubject, setSelectedSubject] = useState('Mathematics');
  const [selectedClass, setSelectedClass] = useState('Grade 7');
  const [selectedStream, setSelectedStream] = useState(''); // Default to empty (All Streams)
  const [marks, setMarks] = useState<MarkEntry[]>([]);
  const [isSaving, setIsSaving] = useState(false);
  const [isGeneratingRemarks, setIsGeneratingRemarks] = useState<string | null>(null);

  useEffect(() => {
    schoolService.getExams().then(setExams);
  }, []);

  useEffect(() => {
    localStorage.setItem('elimusmart_curriculum', JSON.stringify(subjects));
  }, [subjects]);

  // Sync marks whenever filters change while in mark-entry mode
  useEffect(() => {
    if (view === 'mark-entry' && selectedExam) {
      const classStudents = students.filter(s => 
        s.class.toLowerCase() === selectedClass.toLowerCase() && 
        (selectedStream === '' || s.stream.toLowerCase() === selectedStream.toLowerCase())
      );

      const entries: MarkEntry[] = classStudents.map(s => {
        const existing = s.results?.find(r => r.examId === selectedExam.id && r.subject === selectedSubject);
        return {
          studentId: s.id,
          studentName: `${s.firstName} ${s.lastName}`,
          admissionNumber: s.admissionNumber,
          score: existing?.score || 0,
          competency: existing?.competency || CBCGrade.BE,
          remarks: existing?.remarks || ''
        };
      });
      setMarks(entries);
    }
  }, [selectedClass, selectedStream, selectedSubject, selectedExam, view, students]);

  const filteredExams = useMemo(() => {
    return exams.filter(ex => 
      ex.title.toLowerCase().includes(examSearch.toLowerCase()) ||
      ex.type.toLowerCase().includes(examSearch.toLowerCase())
    );
  }, [exams, examSearch]);

  const filteredSubjects = useMemo(() => {
    return subjects.filter(s => 
      s.name.toLowerCase().includes(subjectSearch.toLowerCase()) ||
      s.category.toLowerCase().includes(subjectSearch.toLowerCase())
    );
  }, [subjects, subjectSearch]);

  const handleOpenMarkEntry = (exam: Exam) => {
    setSelectedExam(exam);
    setView('mark-entry');
  };

  const openExamModal = (exam?: Exam) => {
    if (exam) {
      setEditingExam(exam);
      setExamFormData({
        title: exam.title,
        term: exam.term,
        year: exam.year,
        type: exam.type,
        date: exam.date
      });
    } else {
      setEditingExam(null);
      setExamFormData({
        title: '',
        term: schoolConfig?.term || 1,
        year: schoolConfig?.year || new Date().getFullYear(),
        type: 'CAT',
        date: new Date().toISOString().split('T')[0]
      });
    }
    setIsExamModalOpen(true);
  };

  const handleSaveExam = (e: React.FormEvent) => {
    e.preventDefault();
    if (editingExam) {
      setExams(prev => prev.map(ex => 
        ex.id === editingExam.id ? { ...ex, ...examFormData } as Exam : ex
      ));
    } else {
      const newExam: Exam = {
        id: `ex${Date.now()}`,
        title: examFormData.title || 'New Assessment',
        term: examFormData.term || 1,
        year: examFormData.year || new Date().getFullYear(),
        type: examFormData.type as any || 'CAT',
        date: examFormData.date || new Date().toISOString().split('T')[0]
      };
      setExams(prev => [newExam, ...prev]);
    }
    setIsExamModalOpen(false);
  };

  const handleDeleteExam = (id: string) => {
    if (confirm('Are you sure you want to delete this exam and all associated records?')) {
      setExams(prev => prev.filter(ex => ex.id !== id));
    }
  };

  const openSubjectModal = (subject?: Subject) => {
    if (subject) {
      setEditingSubject(subject);
      setSubjectFormData({ 
        name: subject.name, 
        category: subject.category, 
        gradeRange: subject.gradeRange 
      });
    } else {
      setEditingSubject(null);
      setSubjectFormData({ 
        name: '', 
        category: 'STEM', 
        gradeRange: 'Grade 1 - Grade 9' 
      });
    }
    setIsSubjectModalOpen(true);
  };

  const handleSaveSubject = (e: React.FormEvent) => {
    e.preventDefault();
    if (editingSubject) {
      setSubjects(prev => prev.map(s => 
        s.id === editingSubject.id ? { ...s, ...subjectFormData } : s
      ));
    } else {
      const newSub: Subject = {
        id: `sub${Date.now()}`,
        ...subjectFormData
      };
      setSubjects(prev => [...prev, newSub]);
    }
    setIsSubjectModalOpen(false);
  };

  const handleDeleteSubject = (id: string) => {
    if (confirm('Are you sure you want to remove this subject from the school curriculum?')) {
      setSubjects(prev => prev.filter(s => s.id !== id));
    }
  };

  const handleScoreChange = (studentId: string, scoreStr: string) => {
    const score = parseInt(scoreStr) || 0;
    setMarks(prev => prev.map(m => 
      m.studentId === studentId 
        ? { ...m, score, competency: schoolService.calculateCBCGrade(score) } 
        : m
    ));
  };

  const handleRemarkChange = (studentId: string, remarks: string) => {
    setMarks(prev => prev.map(m => m.studentId === studentId ? { ...m, remarks } : m));
  };

  const generateAIRemark = async (student: MarkEntry) => {
    if (!process.env.API_KEY) {
      handleRemarkChange(student.studentId, `${student.studentName} shows ${student.competency} in ${selectedSubject}. Keep it up!`);
      return;
    }

    setIsGeneratingRemarks(student.studentId);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const promptText = `Write a one-sentence professional teacher remark for a student named ${student.studentName} who scored ${student.score}% (CBC level: ${student.competency}) in ${selectedSubject}. Make it encouraging and specific to the grade level ${selectedClass}.`;

      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: promptText
      });
      handleRemarkChange(student.studentId, response.text || 'Commendable performance.');
    } catch (error) {
      console.error(error);
      handleRemarkChange(student.studentId, 'Performance is within expectations.');
    } finally {
      setIsGeneratingRemarks(null);
    }
  };

  const saveMarks = async () => {
    if (marks.length === 0) {
      alert("No student marks to commit.");
      return;
    }

    setIsSaving(true);
    await new Promise(r => setTimeout(r, 1200));

    setStudents(prev => prev.map(student => {
      const markEntry = marks.find(m => m.studentId === student.id);
      if (markEntry && selectedExam) {
        const result: ExamResult = {
          examId: selectedExam.id,
          subject: selectedSubject,
          score: markEntry.score,
          grade: markEntry.score >= 80 ? 'A' : markEntry.score >= 60 ? 'B' : markEntry.score >= 40 ? 'C' : 'D',
          competency: markEntry.competency,
          remarks: markEntry.remarks
        };

        const existingResults = student.results || [];
        const filteredResults = existingResults.filter(r => !(r.examId === selectedExam.id && r.subject === selectedSubject));

        return {
          ...student,
          results: [...filteredResults, result]
        };
      }
      return student;
    }));

    setIsSaving(false);
    alert('Marks successfully recorded and synced with student report cards.');
    setView('exams');
  };

  return (
    <div className="space-y-6 animate-in fade-in duration-500">
      <datalist id="kenyan-classes">
        {KENYAN_CLASSES.map(c => <option key={c} value={c} />)}
      </datalist>
      <datalist id="school-streams">
        <option value="">All Streams</option>
        {SCHOOL_STREAMS.map(s => <option key={s} value={s} />)}
      </datalist>

      <div className="flex flex-col md:flex-row md:items-center justify-between gap-6">
        <div>
          <h1 className="text-3xl font-black text-gray-900 tracking-tighter uppercase italic leading-none">Academics Engine</h1>
          <p className="text-gray-400 font-bold uppercase text-[10px] tracking-[0.3em] mt-3 flex items-center gap-3">
             <span className="w-2 h-2 bg-purple-500 rounded-full animate-pulse"></span>
             CBC Assessment Control • Flexible Routing
          </p>
        </div>

        <div className="flex flex-wrap gap-2 no-print">
          {view === 'exams' && (
            <>
              <button 
                onClick={() => setView('subjects')}
                className="flex items-center space-x-3 bg-white border-2 border-gray-100 text-gray-600 px-6 py-3 rounded-2xl hover:bg-gray-50 hover:border-purple-200 transition-all font-black uppercase text-[10px] tracking-widest shadow-sm"
              >
                <BookMarked className="w-5 h-5 text-purple-500" />
                <span>Curriculum</span>
              </button>
              <button 
                onClick={() => openExamModal()}
                className="flex items-center space-x-3 bg-gray-900 text-white px-8 py-3 rounded-2xl hover:bg-black transition-all font-black uppercase text-[10px] tracking-widest shadow-xl shadow-gray-200 border-b-4 border-black"
              >
                <Plus className="w-5 h-5" />
                <span>Schedule Exam</span>
              </button>
            </>
          )}
          {view === 'subjects' && (
            <>
              <button 
                onClick={() => setView('exams')}
                className="flex items-center space-x-3 bg-white border-2 border-gray-100 text-gray-600 px-6 py-3 rounded-2xl hover:bg-gray-50 transition-all font-black uppercase text-[10px] tracking-widest shadow-sm"
              >
                <ArrowLeft className="w-5 h-5 text-blue-500" />
                <span>Back to Exams</span>
              </button>
              <button 
                onClick={() => openSubjectModal()}
                className="flex items-center space-x-3 bg-purple-600 text-white px-8 py-3 rounded-2xl hover:bg-purple-700 transition-all font-black uppercase text-[10px] tracking-widest shadow-xl shadow-purple-100 border-b-4 border-purple-800"
              >
                <Plus className="w-5 h-5" />
                <span>Add Subject</span>
              </button>
            </>
          )}
        </div>
      </div>

      {/* GLOBAL FILTERS: Visible in both Exams and Mark Entry views */}
      {view !== 'subjects' && (
        <div className="bg-white p-6 rounded-[32px] border-2 border-gray-50 flex flex-col xl:flex-row items-center gap-6 no-print shadow-xl">
           <div className="flex-1 w-full grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
              <div className="space-y-2">
                 <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Academic Target (Class)</label>
                 <div className="flex items-center bg-gray-50 border-2 border-gray-100 rounded-2xl focus-within:border-blue-500 transition-all px-4 py-1 shadow-inner">
                   <Type size={16} className="text-gray-400 mr-2" />
                   <input 
                     list="kenyan-classes"
                     value={selectedClass}
                     placeholder="Select Grade..."
                     onChange={e => setSelectedClass(e.target.value)}
                     className="w-full bg-transparent py-2.5 font-black uppercase text-[11px] outline-none placeholder:text-gray-300"
                   />
                 </div>
              </div>

              <div className="space-y-2">
                 <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest ml-1">Section / Stream</label>
                 <div className="flex items-center bg-gray-50 border-2 border-gray-100 rounded-2xl focus-within:border-blue-500 transition-all px-4 py-1 shadow-inner">
                   <Layers size={16} className="text-gray-400 mr-2" />
                   <input 
                     list="school-streams"
                     value={selectedStream}
                     placeholder="All Streams"
                     onChange={e => setSelectedStream(e.target.value)}
                     className="w-full bg-transparent py-2.5 font-black uppercase text-[11px] outline-none placeholder:text-gray-300"
                   />
                 </div>
              </div>

              <div className="space-y-2">
